import{af as i,z as a,J as t,ab as l}from"./chunks/framework.BPSnAHw5.js";const u=JSON.parse('{"title":"Devices","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"apps/admin/devices/index.md","filePath":"apps/admin/devices/index.md"}'),s={name:"apps/admin/devices/index.md"};function d(r,e,n,o,c,h){return a(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792747255000"},[...e[0]||(e[0]=[l('<h1 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h1><p>The devices page lists all devices that you have access to.</p><p>From here you can view device status, location, and other information. You can also perform actions on devices, such as viewing logs, sending commands, and managing settings.</p><p>A variety of individual and bulk actions are available.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/pHBzHGL.png" alt="Lightbug Admin device list" tabindex="0"><figcaption>Lightbug Admin device list</figcaption></figure><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>The device list shows the following fields:</p><ul><li>Identifiers: Static <a href="/docs/pr/25/terminology/devices#identity">identifiers</a> for the device. <ul><li>ID</li><li>Serial Number</li><li>IMEI</li><li>ICCID</li></ul></li><li>Names <ul><li>Name: User defined name for the device.</li><li>Type: Device type, such as <code>ZeroN</code> etc.</li><li>Tags: User defined <a href="/docs/pr/25/terminology/devices#tags">tags</a> for the device.</li></ul></li><li>Seen <ul><li>Last: Time the device was last seen by the Lightbug platform, this may not be a 1:1 match with when data was last received.</li><li>First: Time the device was fist seen by the Lightbug platform, likely around the time it was manufactured.</li></ul></li><li>Users</li><li>Plan details</li><li>Firmware</li><li>Status <ul><li>Battery</li><li>Enabled</li></ul></li><li><a href="#actions">Actions</a></li></ul><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>Filters can be used to narrow down the list of devices.</p><p>Such as all <code>ZeroN</code> devices.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/JkdXTz6.png" alt="" tabindex="0"><figcaption></figcaption></figure>',12)])])}const f=i(s,[["render",d]]);export{u as __pageData,f as default};
